-- =====================================================================
-- ERP Albion - Usuarios legacy + backfill de articulos.creado_por
--
-- El legacy no tiene una tabla central de usuarios: el login aparece
-- como texto libre en la columna `usuario` de varias tablas (mismo
-- diagnostico que etl/src/steps/02_usuarios.js, que hace este barrido
-- para todo el sistema cuando corre contra MySQL en vivo -- ver ese
-- archivo). Esta migracion hace lo mismo en dos fuentes puntuales
-- (catalogo.articulos y la importacion de ingenieria.maquinas que
-- sigue en 017_import_maquinas.sql), a partir del dump SQL directo
-- (no hay MySQL local disponible en este entorno). 25 usuarios
-- distintos, sin password (login legacy sin credenciales reales,
-- igual criterio que el resto del proyecto).
--
-- catalogo.articulos.creado_por habia quedado NULL en toda la tabla
-- (008_import_articulos.sql no lo resolvia). Se completa aca de paso:
-- 10539/10665 articulos tienen usuario legacy resoluble.
-- =====================================================================

